    "hintEn": "Express the base as $1 + \\frac{2k}{x - k}$. Then the limit is $e^{2k}$.",
    "hintAr": "عبر عن الأساس بالصورة $1 + \\frac{2k}{x - k}$، فتكون النهاية هي هـ^(٢ك).",
