    "titleAr": "نهاية الأساس النسبي المتماثل للعدد النيبيري (k=7)",
    "difficulty": "hots",
    "questionEn": "Evaluate the limit: $$\\lim_{x \\to \\infty} \\left(\\frac{x + 7}{x - 7}\\right)^x$$",
    "questionAr": "احسب قيمة النهاية: $$\\lim_{x \\to \\infty} \\left(\\frac{x + 7}{x - 7}\\right)^x$$",
    "optionsEn": [
      "$e^{14}$",
      "$e^{7}$",
      "$e^{16}$",
      "$e^{18}$"
    ],
